// ✅ Obtener datos del origen (Code3)
const solicitudRaw = $('Code3').first();
const solicitud = solicitudRaw.json || solicitudRaw;

// --- LÓGICA DE FECHAS (HÍBRIDA) ---
let fechaInicioISO, fechaFinISO;

// CASO 1: Vienen listos desde Code3 (start/end)
if (solicitud.start && solicitud.end) {
    fechaInicioISO = solicitud.start; 
    fechaFinISO = solicitud.end;      
} 
// CASO 2: Vienen separados (Lógica antigua de respaldo)
else if (solicitud.Fecha && solicitud.Hora) {
    fechaInicioISO = `${solicitud.Fecha}T${solicitud.Hora}:00`;

    // Calculamos fin manual si no existe
    const duracion = solicitud.duracion_servicio || 105; // 1:45hs default
    const d = new Date(fechaInicioISO);
    d.setMinutes(d.getMinutes() + duracion);

    // Función simple para formatear a ISO local
    const pad = n => n < 10 ? '0' + n : n;
    fechaFinISO = `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:00`;
} else {
    // Error si no hay datos
    return [{
        json: {
            error: 'Faltan campos Fecha/Hora o start/end',
            recibido: solicitud
        }
    }];
}

// ✅ Extraer strings para lógica de conflicto
const solicitudFecha = fechaInicioISO.split('T')[0];
// Aseguramos formato HH:MM
const solicitudInicio = fechaInicioISO.split('T')[1].substring(0, 5); 
const solicitudFin = fechaFinISO.split('T')[1].substring(0, 5);

// ⚠️ CAMBIO CRÍTICO: Usamos 'SanMartin' como en tu primer código
const pilarOcupados = $('Campana').all().map(i => i.json).flat();

// ✅ Función de Conflictos
function tieneConflicto(fecha, inicio, fin, ocupados) {
  if (!Array.isArray(ocupados) || ocupados.length === 0) return false;

  const inicioMin = timeToMinutes(inicio);
  const finMin = timeToMinutes(fin);

  return ocupados.some(o => {
    if (!o.dia || !o.inicio || !o.final) return false; 

    if (o.dia !== fecha) return false;
    const oIni = timeToMinutes(o.inicio);
    const oFin = timeToMinutes(o.final);
    // Verificar superposición
    return inicioMin < oFin && finMin > oIni;
  });
}

// ✅ Disponibilidad
const p1Disp = !tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, pilarOcupados);

// ✅ Recuperar ID de Calendario (Prioridad: Code3 > Get_Reglas1)
let calendarId = solicitud.calendarId || solicitud.Id_Calendario;

if (!calendarId) {
    const reglasRaw = $('Get_Reglas1').first();
    const reglas = reglasRaw.json || reglasRaw;
    calendarId = reglas.Id_Calendario;
}

if (!p1Disp) {
  return [{
    json: {
      error: `Conflicto de disponibilidad detectado para ${solicitudFecha} ${solicitudInicio}`,
      ocupados: pilarOcupados
    }
  }];
}

// =========================================================
// 🧹 SECCIÓN DE LIMPIEZA DE DATOS (REGEX)
// =========================================================

// Unimos description y resumen para analizar todo el texto disponible
const textoFull = (solicitud.description || "") + " " + (solicitud.resumen || "");

// 1. Extraer CLIENTE (Busca texto después de "| Cliente:")
const matchCliente = textoFull.match(/[|]+\s*Cliente:\s*([^|]+)/i);
const clienteLimpio = matchCliente ? matchCliente[1].trim() : "Cliente";

// 2. Extraer PATENTE (Forzamos mayúsculas)
const matchPatente = textoFull.match(/[|]+\s*Patente:\s*([^|]+)/i);
const patenteLimpia = matchPatente ? matchPatente[1].trim().toUpperCase() : (solicitud.patente || "S/P");

// 3. Extraer MODELO (Forzamos mayúsculas)
const matchModelo = textoFull.match(/[|]+\s*Modelo:\s*([^|]+)/i);
const modeloLimpio = matchModelo ? matchModelo[1].trim().toUpperCase() : "NO DETECTADO";

// 4. Extraer SERVICIO
const matchServicio = textoFull.match(/[|]+\s*Servicio:\s*([^|]+)/i);
const servicioLimpio = matchServicio ? matchServicio[1].trim() : "Service Taller";

// Armamos textos finales para Google Calendar
const tituloEvento = `${servicioLimpio} - ${modeloLimpio} (${patenteLimpia})`;
const descripcionFinal = `Cliente: ${clienteLimpio}\nVehículo: ${modeloLimpio}\nPatente: ${patenteLimpia}\nServicio: ${servicioLimpio}\n\nNota Original:\n${textoFull}`;


// ✅ RESULTADO FINAL PARA EL NODO "CREATE AN EVENT"
return [{
  json: {
    // --- 1. Datos estandarizados para Google Calendar Node ---
    calendarId: calendarId,
    start: fechaInicioISO, 
    end: fechaFinISO,
    summary: tituloEvento, 
    description: descripcionFinal, // Ahora usa la descripción limpia y formateada

    // --- 2. Datos legacy (por si tu nodo final usa estas variables) ---
    Calendar: calendarId,
    Fecha: fechaInicioISO, 
    Fin: fechaFinISO,

    // --- 3. 🟢 DATOS LIMPIOS INDIVIDUALES (NIVEL RAÍZ) ---
    // Agregamos esto para que puedas usar {{ $json.cliente_limpio }} en otros nodos
    cliente_limpio: clienteLimpio,
    patente_limpia: patenteLimpia,
    modelo_limpio: modeloLimpio,
    servicio_limpio: servicioLimpio,

    // --- 4. Agrupados en objeto (opcional) ---
    datos_extra: {
        cliente: clienteLimpio,
        patente: patenteLimpia,
        modelo: modeloLimpio,
        servicio: servicioLimpio,
        id_turno: solicitud.id
    },

    // --- 5. Mantener datos originales por las dudas ---
    ...solicitud
  }
}];

const items = $input.all();
const returnItems = [];

// Verificar si hay items
if (!items || items.length === 0) {
  return [];
}

for (const item of items) {
  // Verificar que el item tenga la estructura correcta
  if (!item || !item.json || !item.json.start || !item.json.start.dateTime) {
    continue; // Saltar este item si no tiene la estructura correcta
  }

  let data = item.json;

  const dia = data.start.dateTime.split('T')[0];
  const inicio = data.start.dateTime.split('T')[1].substring(0, 5);
  const final = data.end.dateTime.split('T')[1].substring(0, 5);

  returnItems.push({
    json: {
      dia: dia,
      inicio: inicio, 
      final: final
    }
  });
}

return returnItems;
